// Aplatit la sortie NocoDB v3 {id, fields:{}} au format plat du noeud
// Airtable historique : {...champs, id} -> aucune expression aval a changer.
return $input.all().map(i => ({ json: { ...(i.json.fields || {}), id: i.json.id } }));

// UUID generator
function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

const allRows = $input.all().map(i => i.json);
const courses = {};

for (const row of allRows) {
  const title = (row.Cours || '').trim();
  if (!title) continue;

  if (!courses[title]) {
    courses[title] = { title, modules: {}, ids: [], all_ready: true };
  }

  const c = courses[title];
  c.ids.push(row.id);

  const contenu = (row.Status_Contenu || '').trim().toLowerCase();
  const quiz = (row.Status_Quiz || '').trim().toLowerCase();
  const pub = (row.Status_Publication || '').trim().toLowerCase();

  // Readiness check — contenu must be produit or n/a, quiz must be produit or n/a
  if (contenu !== 'produit' && contenu !== 'n/a') c.all_ready = false;
  if (quiz !== 'produit' && quiz !== 'n/a') c.all_ready = false;
  if (pub === 'pending_review' || pub === 'published') c.all_ready = false;

  const modKey = row.Module || 'Module';
  if (!c.modules[modKey]) {
    c.modules[modKey] = { raw: modKey, lessons: [] };
  }

  // Ajouter TOUTES les lignes (text, video, quiz, mission, resource)
  c.modules[modKey].lessons.push({
    lecon: row.Lecon || '',
    type: row.Type || 'text',
    duree: row.Duree || '4 min'
  });
}

const ready = Object.values(courses).filter(c => c.all_ready && c.ids.length > 0);

if (ready.length === 0) {
  return [{ json: { _empty: true, message: 'Aucun cours pret a publier' } }];
}

// Lire la duree originale depuis "Banque Idees Cours" — on la propage depuis le titre
// Pour l'instant on calcule la duree totale depuis les lecons
return ready.map(c => {
  const modulesArr = Object.values(c.modules).map((mod, mi) => {
    const modMatch = mod.raw.match(/^M(\d+):\s*(.+)$/);
    return {
      id: uuid(),
      title: modMatch ? modMatch[2].trim() : mod.raw,
      order: modMatch ? parseInt(modMatch[1]) : mi + 1,
      lessons: mod.lessons.map((l, li) => {
        const lMatch = l.lecon.match(/^(?:L(\d+)|Quiz|Mission):\s*(.+)$/);
        const lessonNum = lMatch && lMatch[1] ? parseInt(lMatch[1]) : li + 1;
        const lessonTitle = lMatch ? lMatch[2].trim() : l.lecon;
        return {
          id: uuid(),
          title: lessonTitle,
          type: l.type || 'text',
          duration: l.duree || '4 min',
          content: '',
          order: li + 1,
          isFree: mi === 0 && li === 0
        };
      })
    };
  });

  const totalLessons = modulesArr.reduce((s, m) => s + m.lessons.length, 0);
  const totalMinutes = modulesArr.reduce((s, m) => s + m.lessons.reduce((ls, l) => {
    const dm = (l.duration || '').match(/(\d+)/);
    return ls + (dm ? parseInt(dm[1]) : 4);
  }, 0), 0);

  // Duree arrondie en heures
  const hours = Math.round(totalMinutes / 60 * 10) / 10;

  return {
    json: {
      course_title: c.title,
      modules: modulesArr,
      total_modules: modulesArr.length,
      total_lessons: totalLessons,
      estimated_hours: hours,
      duration_display: hours >= 1 ? hours + 'h' : totalMinutes + ' min',
      ids: c.ids,
      thumbnail_prompt: 'Image de couverture pour le cours: ' + c.title + ' — Formation marketing digital Afrique francophone'
    }
  };
});

// runOnceForEachItem
const input = $input.item.json;
const orig = $('IMG1 — Normaliser').item.json;
let prompt = orig.prompt;
try {
  let text = input.content?.parts ? input.content.parts.map(p=>p.text||'').join('') : typeof input === 'string' ? input : '';
  if (text) { const m = text.match(/\{[\s\S]*\}/); if (m) { const p = JSON.parse(m[0]); if (p.enhanced_prompt) prompt = p.enhanced_prompt; } }
} catch(e) {}
if (!prompt) prompt = orig.prompt;
return { json: { ...orig, prompt, original_prompt: orig.prompt } };

// runOnceForEachItem
const input = $input.item;
const p = $('IMG3 — Parse prompt').item.json;
const now = new Date().toISOString().replace(/[:.]/g,'-').substring(0,19);
const slug = (p.slug||'formation').substring(0,60);
const r2_key = 'formations/' + slug + '-' + now + '.png';
const result = { json: { ...p, filename: slug+'-'+now+'.png', r2_key, r2_bucket: 'maxmorrys-lms', generated_at: new Date().toISOString() } };
if (input.binary) result.binary = input.binary;
return result;

// runOnceForEachItem
const meta = $('IMG5 — Preparer R2').item.json;
const url = 'https://pub-98fc057dc71948c7bd129a674b4bcec8.r2.dev/' + meta.r2_key;
return { json: { public_url: url, formation_passthrough: meta.formation_passthrough, ids: meta.ids, slug: meta.slug, total_modules: meta.total_modules, total_lessons: meta.total_lessons, estimated_hours: meta.estimated_hours } };

// runOnceForEachItem
const img = $json;
const formation = { ...img.formation_passthrough };
if (img.public_url) { formation.coverImage = img.public_url; formation.ogImage = img.public_url; }
return { json: { formation, slug: img.slug, ids: img.ids, total_modules: img.total_modules, total_lessons: img.total_lessons, estimated_hours: img.estimated_hours, image_url: img.public_url } };

// runOnceForEachItem — Serialize Formation to Firestore REST format
function toFV(val) {
  if (val === null || val === undefined) return { nullValue: null };
  if (typeof val === 'string') return { stringValue: val };
  if (typeof val === 'number') return Number.isInteger(val) ? { integerValue: String(val) } : { doubleValue: val };
  if (typeof val === 'boolean') return { booleanValue: val };
  if (Array.isArray(val)) return { arrayValue: { values: val.map(toFV) } };
  if (typeof val === 'object') { const f = {}; for (const [k,v] of Object.entries(val)) f[k] = toFV(v); return { mapValue: { fields: f } }; }
  return { stringValue: String(val) };
}
const f = $json.formation;
const fields = {};
for (const [k,v] of Object.entries(f)) fields[k] = toFV(v);
return { json: { firestoreDoc: { fields }, slug: $json.slug, ids: $json.ids, course_title: f.title, total_modules: $json.total_modules, total_lessons: $json.total_lessons, estimated_hours: $json.estimated_hours, image_url: $json.image_url } };

// runOnceForAllItems — flatten ids from all cours for Sheets update
const allItems = $input.all();
const results = [];

for (const item of allItems) {
  // The input comes from Firestore write — ids is in the Serialize node's output
  // We need to go back to get ids from the Build node via the chain
  // Actually the Firestore response doesn't contain ids — it's in Serialize's input

  // Get all items from Group node which has ids
  const groupItems = $('Group — Cours complets prêts').all();

  for (const gItem of groupItems) {
    const ids = gItem.json.ids || [];
    for (const rn of ids) {
      results.push({ json: { id: rn, Status_Publication: 'pending_review' } });
    }
  }

  break; // Only need to do this once since Group has all the data
}

if (results.length === 0) {
  return [{ json: { id: -1, Status_Publication: 'skip', _no_updates: true } }];
}

return results;

